// Client-Side JavaScript (Connecting to a WebSocket)

// 1. Open the connection (Notice the 'ws://' protocol instead of 'http://')
const socket = new WebSocket('ws://localhost:8080');

// 2. Listen for messages pushed from the server
socket.addEventListener('message', (event) => {
  console.log('Server says: ', event.data);
  // Instantly update the React UI with the new chat message
});

// 3. Send a message to the server at any time
document.getElementById('sendBtn').onclick = () => {
  socket.send(JSON.stringify({ text: "Hello Server!" }));
};
